package com.karshop.productimage.controller;

import java.io.IOException;


import com.karshop.product.model.ProductService;
import com.karshop.product.model.ProductVO;


import com.karshop.productimage.model.ProductImageRepository;
import com.karshop.productimage.model.ProductImageService;
import com.karshop.productimage.model.ProductImageVO;
import jakarta.servlet.ServletOutputStream;

import jakarta.servlet.http.HttpServlet;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Controller;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;

@Controller
@RequestMapping("/product")
public class DisplayImageController extends HttpServlet {

    @Autowired
    private ProductService productService;

    @Autowired
    private ProductImageService productImageService;

    @GetMapping("/displayMain")
    public void displayMain(@RequestParam("prodNo") String prodNo, HttpServletRequest req, HttpServletResponse res) throws IOException {
        res.setContentType("image/jpeg");
        ServletOutputStream out = res.getOutputStream();

        try{
            ProductVO productVO = productService.getOneProduct(Integer.valueOf(prodNo));
            byte[] pic = productVO.getProductImage().get(0).getUpFile();
            out.write(pic);
        }catch(Exception e){
            byte[] buf =  java.util.Base64.getDecoder().decode("");
            out.write(buf);
        }

    }

    @GetMapping("displayDetail")
    public void displayDetail(@RequestParam("imgNo") String imgNo, HttpServletRequest req, HttpServletResponse res) throws IOException{
        res.setContentType("image/jpeg");
        ServletOutputStream out = res.getOutputStream();

        try{
            ProductImageVO  piVO = productImageService.getOneImage(Integer.valueOf(imgNo));
            byte[] pic = piVO.getUpFile();
            out.write(pic);
        }catch(Exception e){
            byte[] buf =  java.util.Base64.getDecoder().decode("");
            out.write(buf);
        }
    }


}